const TOPICS = new Set(["l", "w", "m", "s"])

export function cardFacets(id, topic = "s") {
  const key = id === "magician" ? "mag" : id
  const found = FACETS[key]
  if (!found) return []
  const sphere = TOPICS.has(topic) ? topic : "s"
  return (found[sphere] || found.s || []).slice()
}

